files.content:
.rangeslider {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  inline-size: 100%;
}
.rangeslider[data-disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}

.rangeslider-labelrow {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--space-3);
}
.rangeslider-label {
  font-size: var(--font-sm);
  color: var(--foreground);
}
.rangeslider-value {
  font-size: var(--font-sm);
  font-variant-numeric: tabular-nums;
  color: var(--muted-foreground);
}

/* One grid cell stacks the rail, the fill and both inputs. The inputs ignore
 * the pointer except on their thumbs, which is what lets two of them share a
 * single track. */
.rangeslider-track { display: grid; }
.rangeslider-track > * { grid-area: 1 / 1; }

.rangeslider-rail {
  align-self: center;
  block-size: var(--space-1);
  border-radius: var(--radius-full);
  background: var(--input);
}
.rangeslider-fill {
  position: relative;
  align-self: center;
  block-size: var(--space-1);
  border-radius: var(--radius-full);
  background: var(--primary);
}

.rangeslider-input {
  inline-size: 100%;
  block-size: var(--space-4);
  margin: 0;
  appearance: none;
  background: transparent;
  pointer-events: none;
}
.rangeslider-input[data-top] { z-index: 1; }
.rangeslider-input:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
  border-radius: var(--radius-full);
}

.rangeslider-input::-webkit-slider-runnable-track {
  block-size: var(--space-4);
  background: transparent;
}
.rangeslider-input::-moz-range-track {
  block-size: var(--space-4);
  background: transparent;
}

.rangeslider-input::-webkit-slider-thumb {
  appearance: none;
  pointer-events: auto;
  inline-size: var(--space-4);
  block-size: var(--space-4);
  border-radius: var(--radius-full);
  background: var(--primary);
  border: 2px solid var(--background);
  box-shadow: var(--shadow-sm);
  cursor: pointer;
}

/* The thumb answers the pointer — see the note in Slider.css. */
.rangeslider-input:hover::-webkit-slider-thumb { background: var(--primary-hover); }
.rangeslider-input:active::-webkit-slider-thumb { background: var(--primary-active); }
.rangeslider-input:hover::-moz-range-thumb { background: var(--primary-hover); }
.rangeslider-input:active::-moz-range-thumb { background: var(--primary-active); }

.rangeslider-input::-moz-range-thumb {
  pointer-events: auto;
  inline-size: var(--space-4);
  block-size: var(--space-4);
  border-radius: var(--radius-full);
  background: var(--primary);
  border: 2px solid var(--background);
  box-shadow: var(--shadow-sm);
  cursor: pointer;
}

import './RangeSlider.css'
import { useId } from 'react'
import { cn } from '../lib/cn'

type Props = {
  /** The selected span, start then end. */
  value: [number, number]
  onChange: (value: [number, number]) => void
  min?: number
  max?: number
  step?: number
  /** Accessible name; each thumb announces it plus "start" / "end". */
  label: string
  /** Show the current span at the inline-end of the label row. */
  showValue?: boolean
  /** Formats one bound of the shown span (e.g. `(v) => `${v}%``). */
  formatValue?: (value: number) => string
  disabled?: boolean
  className?: string
}

/* A bounded pair on one track: a price between two values, any filter with a
 * "from" and a "to" on the same scale. Two native range inputs share the
 * track, so the keyboard contract comes for free; each thumb clamps against
 * the other instead of crossing it. Single value? That is <Slider>. 
   *
   * Copy: the label names the span and its unit; the two thumbs need one name
   * between them, not "min" and "max".
   */
export function RangeSlider({
  value, onChange, min = 0, max = 100, step = 1, label, showValue, formatValue, disabled, className,
}: Props) {
  const id = useId()
  const [start, end] = value
  const fmt = (v: number) => (formatValue ? formatValue(v) : String(v))
  const span = max - min
  const pctStart = span === 0 ? 0 : ((start - min) / span) * 100
  const pctEnd = span === 0 ? 0 : ((end - min) / span) * 100

  return (
    <div className={cn('rangeslider', className)} data-disabled={disabled || undefined}>
      <div className="rangeslider-labelrow">
        <label className="rangeslider-label" htmlFor={id}>{label}</label>
        {showValue && (
          <span className="rangeslider-value" aria-hidden="true">
            {fmt(start)} to {fmt(end)}
          </span>
        )}
      </div>
      <div className="rangeslider-track">
        <div className="rangeslider-rail" />
        <div
          className="rangeslider-fill"
          style={{ insetInlineStart: `${pctStart}%`, inlineSize: `${pctEnd - pctStart}%` }}
        />
        <input
          id={id}
          type="range"
          className="rangeslider-input"
          min={min}
          max={max}
          step={step}
          value={start}
          disabled={disabled}
          aria-label={`${label} start`}
          /* When both thumbs sit in the upper half the start input renders on
           * top, so a pair collapsed at the maximum can still be pulled apart. */
          data-top={start > (min + max) / 2 || undefined}
          onChange={(e) => onChange([Math.min(Number(e.target.value), end), end])}
        />
        <input
          type="range"
          className="rangeslider-input"
          min={min}
          max={max}
          step={step}
          value={end}
          disabled={disabled}
          aria-label={`${label} end`}
          onChange={(e) => onChange([start, Math.max(Number(e.target.value), start)])}
        />
      </div>
    </div>
  )
}
